mapper.select:
select *
from cr_single_room


        business_template_id = #{business_template_id}

    and

        user_id = #{user_id}

select *
from cr_business_template T1
left join cr_single_template T2 on T1.resource_id = T2.business_template_id
left join cr_single_room R1 on T1.resource_id = R1.business_template_id and R1.user_id = #{user_id}


    T1.business_type = #{business_type}
    and (
    T1.create_user_id = #{user_id}
    or (T1.read_auth_ids like #{organization_id} and read_auth_type = 2)
    or read_auth_type = 1
    )

        and T2.sub_type = #{category}


        and T1.difficulty = #{difficult}



        and T1.name like #{pattern}


    and T1.resource_id in (
        select distinct business_template_id from cr_title_business_template where title_id in (
            select resource_id from cr_title where name = #{title}
        )
    )


order by R1.start_time desc, T1.name asc

select business_template_id, date_format(start_time, '%m-%d') as `date`, count(date_format(start_time, '%m-%d'))
as `count` from cr_train_record
where business_type = #{business_type}
and business_template_id in

    #{template_id}

and date_format(start_time, '%Y-%m-%d') in
#{date_item}
group by business_template_id, date_format(start_time, '%m-%d');

select count(id)
from cr_single_room
where user_id = #{userId}
